commands.cmd:
set -u
PIN=$(python3 -c '
import json, glob
pins = sorted({w["pin"] for f in glob.glob("catalogs/landscape/*.json") for l in json.load(open(f)).get("layers", []) for w in (l.get("winners") or []) if w.get("component_id") == "inspect-ai"})
assert pins == ["inspect-ai0.3.266; source ec4dfc6953784dc45b79de3147530c89868c6e26"], pins
print("catalogs/landscape winner pin:", pins[0])
') || { echo "FAIL: the catalogs/landscape winner pins for inspect-ai are not exactly inspect-ai0.3.266"; exit 1; }
T=$(mktemp -d) || { echo "FAIL: mktemp -d"; exit 1; }
trap 'rm -rf "$T"' EXIT
timeout 20 curl -fsS -o "$T/meta.json" https://pypi.org/pypi/inspect-ai/0.3.266/json || { echo "FAIL: PyPI JSON API fetch for inspect-ai 0.3.266 exited $?"; exit 1; }
python3 -c '
import json, sys
d = json.load(open(sys.argv[1] + "/meta.json"))
w = [f for f in d["urls"] if f["packagetype"] == "bdist_wheel"]
assert len(w) == 1, [f["filename"] for f in w]
for key, value in (("name", w[0]["filename"]), ("url", w[0]["url"]), ("sha256", w[0]["digests"]["sha256"])):
    open(sys.argv[1] + "/wheel." + key, "w").write(value)
' "$T" || { echo "FAIL: the PyPI metadata for inspect-ai 0.3.266 does not list exactly one wheel"; exit 1; }
WNAME=$(cat "$T/wheel.name") && WURL=$(cat "$T/wheel.url") && WSHA=$(cat "$T/wheel.sha256") || { echo "FAIL: reading the PyPI wheel entry"; exit 1; }
[ "$WSHA" = "e30e1c2abf2844a9db221d5307b9b380e2da5fb1d29a9f2bff9094262c1044e6" ] || { echo "FAIL: PyPI declares sha256 $WSHA for $WNAME, not the expected e30e1c2abf2844a9db221d5307b9b380e2da5fb1d29a9f2bff9094262c1044e6"; exit 1; }
timeout 60 curl -fsS -o "$T/wheel.whl" "$WURL" || { echo "FAIL: downloading $WNAME exited $?"; exit 1; }
S=$(sha256sum "$T/wheel.whl") || { echo "FAIL: sha256sum exited $?"; exit 1; }
[ "${S%% *}" = "$WSHA" ] || { echo "FAIL: the downloaded $WNAME hashes to ${S%% *}, not the PyPI-declared $WSHA"; exit 1; }
echo "PASS inspect-ai 0.3.266: winner pin; $WNAME downloaded from PyPI hashes to its PyPI-declared sha256"
echo "sha256 $WSHA"
echo "$PIN"

set -u
D="$HOME/.local/share/codex-ecosystem/python-tools"
B="$HOME/.local/share/codex-ecosystem/bin"
TL=$(UV_TOOL_DIR="$D" UV_TOOL_BIN_DIR="$B" timeout 30 uv tool list --show-version-specifiers --show-python --show-paths) || { echo "FAIL: uv tool list exited $?"; exit 1; }
ROW=$(printf '%s\n' "$TL" | grep -A1 '^inspect-ai ') || { echo "FAIL: uv tool list shows no inspect-ai tool"; exit 1; }
printf '%s\n' "$ROW" | grep -qxF "inspect-ai v0.3.266 [required: ==0.3.266] [CPython 3.13.15] ($D/inspect-ai)" || { echo "FAIL: unexpected uv tool list row: $ROW"; exit 1; }
printf '%s\n' "$ROW" | grep -qxF -- "- inspect ($B/inspect)" || { echo "FAIL: uv tool list does not show the inspect entrypoint in $B: $ROW"; exit 1; }
C=$(timeout 30 uv pip check --python "$D/inspect-ai/bin/python" 2>&1) || { echo "FAIL: uv pip check exited $?: $C"; exit 1; }
T=$(mktemp -d) || { echo "FAIL: mktemp -d"; exit 1; }
trap 'rm -rf "$T"' EXIT
timeout 30 uv venv --offline --quiet --python "$D/inspect-ai/bin/python" "$T/v" || { echo "FAIL: creating the control venv exited $?"; exit 1; }
SITE=$("$T/v/bin/python" -c 'import sysconfig; print(sysconfig.get_path("purelib"))') || { echo "FAIL: reading the control venv site-packages path"; exit 1; }
mkdir "$SITE/ctl_probe-0.0.0.dist-info" \
&& printf 'Metadata-Version: 2.1\nName: ctl-probe\nVersion: 0.0.0\nRequires-Dist: ctl-absent-dep\n' >"$SITE/ctl_probe-0.0.0.dist-info/METADATA" \
&& printf 'Wheel-Version: 1.0\nGenerator: control\nRoot-Is-Purelib: true\nTag: py3-none-any\n' >"$SITE/ctl_probe-0.0.0.dist-info/WHEEL" \
&& : >"$SITE/ctl_probe-0.0.0.dist-info/RECORD" || { echo "FAIL: writing the control package"; exit 1; }
N=$(timeout 30 uv pip check --python "$T/v/bin/python" 2>&1); NRC=$?
[ "$NRC" -ne 0 ] || { echo "FAIL: uv pip check exited 0 on the control venv, whose ctl-probe requires the absent ctl-absent-dep: $N"; exit 1; }
CTL=$(printf '%s\n' "$N" | grep -F 'requires `ctl-absent-dep`') || { echo "FAIL: uv pip check on the control venv (exit $NRC) does not report the missing dependency: $N"; exit 1; }
echo "PASS uv tool list, uv pip check, control"
echo "$ROW"
printf '%s\n' "$C" | grep -v '^Using Python'
echo "control exit $NRC: $CTL"

set -u
D="$HOME/.local/share/codex-ecosystem/python-tools"
p=$(command -v inspect) || { echo "FAIL: inspect is not on PATH"; exit 1; }
r=$(readlink -f "$p") || { echo "FAIL: readlink -f $p exited $?"; exit 1; }
[ "$r" = "$D/inspect-ai/bin/inspect" ] || { echo "FAIL: inspect on PATH ($p) resolves to $r, not $D/inspect-ai/bin/inspect"; exit 1; }
V=$(DO_NOT_TRACK=1 timeout 20 inspect --version) || { echo "FAIL: inspect --version exited $?"; exit 1; }
[ "$V" = "0.3.266" ] || { echo "FAIL: inspect --version printed '$V', expected 0.3.266"; exit 1; }
M=$("$D/inspect-ai/bin/python" -c 'import importlib.metadata as m, platform; print(m.version("inspect-ai"), "on", platform.python_implementation(), platform.python_version())') || { echo "FAIL: importlib.metadata in the tool environment exited $?"; exit 1; }
[ "${M%% *}" = "0.3.266" ] || { echo "FAIL: importlib.metadata reports inspect-ai $M, expected 0.3.266"; exit 1; }
echo "PASS inspect --version $V | importlib.metadata inspect-ai $M"
echo "PATH inspect: $p -> $r"
